using Microsoft.ML;
using Microsoft.ML.Data;

var ml = new MLContext(seed: 0);
var data = ml.Data.LoadFromEnumerable(new[] {
    new House { Size = 50,  Price = 100 },
    new House { Size = 80,  Price = 160 },
    new House { Size = 120, Price = 240 } });

var pipeline = ml.Transforms.Concatenate("Features", nameof(House.Size))
    .Append(ml.Regression.Trainers.Sdca(labelColumnName: nameof(House.Price)));
var model = pipeline.Fit(data);

var engine = ml.Model.CreatePredictionEngine<House, Pred>(model);
Console.WriteLine(engine.Predict(new House { Size = 100 }).Score);

public class House { public float Size { get; set; } public float Price { get; set; } }
public class Pred { [ColumnName("Score")] public float Score { get; set; } }

