// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

contract Registry {
    mapping(bytes32 => address) public ownerOf;
    event Registered(bytes32 indexed cid, address indexed owner);

    function register(bytes32 cid) external {
        require(ownerOf[cid] == address(0), "exists");
        ownerOf[cid] = msg.sender;
        emit Registered(cid, msg.sender);
    }
}
